// ZoomInfo GTM Data API: GET /gtm/data/v1/users/usage.
// Documented response: UsageResponse -> data[] -> attributes.usage[] with
// limitType, description, totalLimit, currentUsage, usageRemaining.
// limitType values: request, record, uniqueID, webSightsApiRequest, webSightsApiRecord.
// The schema carries NO reset date, so the contract-period end has to come from an env var.

const out = [];
const now = new Date().toISOString();

for (const item of $input.all()) {
  const res = item.json;
  const status = res.statusCode ?? 200;

  if (status === 401 || status === 403) {
    // Never emit a zero-usage record on an auth failure: a zero looks like
    // "nothing was spent" downstream and would suppress every drift alert.
    out.push({ json: { vendor: 'zoominfo', ok: false, reason: `auth_${status}`, checkedAt: now } });
    continue;
  }
  if (status === 429) {
    out.push({ json: { vendor: 'zoominfo', ok: false, reason: 'rate_limited', retryAfter: res.headers?.['retry-after'] ?? null, checkedAt: now } });
    continue;
  }
  if (status >= 400) {
    out.push({ json: { vendor: 'zoominfo', ok: false, reason: `http_${status}`, checkedAt: now } });
    continue;
  }

  const body = res.body ?? res;
  const resources = body.data ?? body.UsageResponse?.data ?? [];
  const rows = [];
  for (const r of Array.isArray(resources) ? resources : [resources]) {
    const usage = r?.attributes?.usage ?? [];
    for (const u of usage) rows.push(u);
  }

  if (rows.length === 0) {
    out.push({ json: { vendor: 'zoominfo', ok: false, reason: 'empty_usage_array', checkedAt: now } });
    continue;
  }

  for (const u of rows) {
    const total = Number(u.totalLimit ?? 0);
    const used = Number(u.currentUsage ?? 0);
    const remaining = u.usageRemaining === undefined || u.usageRemaining === null
      ? (total - used)
      : Number(u.usageRemaining);
    out.push({
      json: {
        vendor: 'zoominfo',
        ok: true,
        unit: u.limitType,              // request | record | uniqueID | webSights*
        description: u.description ?? null,
        allowance: total,
        used,
        remaining,
        // Only the record limit maps to what ZoomInfo bills as a credit; request
        // limits are throughput, not spend. Downstream cost maths keys off this flag.
        billable: u.limitType === 'record' || u.limitType === 'uniqueID',
        checkedAt: now,
      },
    });
  }
}

return out;

// Apollo publishes no credit-balance endpoint. usage_stats returns, per endpoint,
// { day|hour|minute: { limit, consumed, left_over } } — those are REQUESTS.
// Credits are derived from Apollo's documented per-call cost, which is why this
// node emits a floor and a ceiling instead of one number:
//   * people match: 1 credit for demographics/email, +8 if a mobile phone is returned (1-9)
//   * people bulk_match: up to 10 people per request -> 1..90 credits per request
//   * organization enrich: 1 credit per organization
//   * search endpoints: 1 credit per page
//   * create/update/list/manage endpoints: 0 credits
// A single request therefore cannot be converted to an exact credit count. The
// authoritative number is the call-site ledger; this bracket is the reconciliation bound.

const COST = {
  'api/v1/people/match':              { min: 0, max: 9,  note: '1 email/demographics, +8 mobile' },
  'api/v1/people/bulk_match':         { min: 0, max: 90, note: 'up to 10 people/request x 1-9' },
  'api/v1/organizations/enrich':      { min: 0, max: 1,  note: '1 per organization' },
  'api/v1/organizations/bulk_enrich': { min: 0, max: 10, note: 'up to 10 orgs/request' },
  'api/v1/mixed_companies/search':    { min: 0, max: 1,  note: '1 per page' },
  'api/v1/organizations/job_postings':{ min: 0, max: 1,  note: '1 per page' },
  'api/v1/news_articles/search':      { min: 0, max: 1,  note: '1 per page' },
};

const now = new Date().toISOString();
const item = $input.first().json;
const status = item.statusCode ?? 200;

if (status >= 400) {
  return [{ json: { vendor: 'apollo', ok: false, reason: `http_${status}`, checkedAt: now } }];
}

const body = item.body ?? item;
let floor = 0, ceiling = 0, requests = 0;
const perEndpoint = [];

for (const [endpoint, windows] of Object.entries(body)) {
  const day = windows?.day;
  if (!day) continue;
  const consumed = Number(day.consumed ?? 0);
  requests += consumed;
  const key = endpoint.replace(/^\/+/, '');
  const cost = COST[key];
  if (!cost) continue;                       // non-billable endpoint
  floor += consumed > 0 ? consumed : 0;      // >=1 credit only if the call returned billable data
  ceiling += consumed * cost.max;
  perEndpoint.push({ endpoint: key, requestsToday: consumed, creditCeiling: consumed * cost.max, note: cost.note });
}

return [{
  json: {
    vendor: 'apollo',
    ok: true,
    unit: 'credit',
    requestsToday: requests,
    derivedCreditFloor: floor,
    derivedCreditCeiling: ceiling,
    perEndpoint,
    // Apollo grants credits per billing cycle and they do not roll over; the cycle
    // anchor is not exposed by the API, so it comes from an env var.
    cycleEnd: $env.APOLLO_CYCLE_END || null,
    allowance: Number($env.APOLLO_CREDIT_ALLOWANCE || 0) || null,
    checkedAt: now,
  },
}];

// Clay exposes usage through Settings → Usage (breakdowns by workbook/table,
// integration and signal, plus separate API and MCP tabs) with CSV export.
// There is no public balance endpoint, so this branch reads the export.
// Required headers are asserted: if Clay renames a column the node throws rather
// than emitting zeros, because a silent zero reads downstream as "spend stopped".

const REQUIRED = ['date', 'credits'];
const now = new Date().toISOString();
const res = $input.first().json;
const status = res.statusCode ?? 200;

if (status >= 400) {
  return [{ json: { vendor: 'clay', ok: false, reason: `http_${status}`, checkedAt: now } }];
}

const text = String(res.body ?? '').trim();
if (!text) {
  return [{ json: { vendor: 'clay', ok: false, reason: 'empty_export', checkedAt: now } }];
}

const lines = text.split(/\r?\n/).filter((l) => l.trim().length > 0);
const split = (line) => {
  const cells = [];
  let cur = '', quoted = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (ch === '"') { quoted = !quoted; continue; }
    if (ch === ',' && !quoted) { cells.push(cur); cur = ''; continue; }
    cur += ch;
  }
  cells.push(cur);
  return cells.map((c) => c.trim());
};

const header = split(lines[0]).map((h) => h.toLowerCase());
const idx = (want) => header.findIndex((h) => h === want || h.includes(want));
for (const req of REQUIRED) {
  if (idx(req) === -1) {
    throw new Error(`Clay export is missing a "${req}" column. Headers seen: ${header.join(' | ')}. Fix the export or update the header map in this node.`);
  }
}

const iDate = idx('date');
const iCredits = idx('credits');
const iActions = idx('action');
const iTable = idx('table');
const iIntegration = idx('integration');

const byDay = {};
for (const line of lines.slice(1)) {
  const cells = split(line);
  const day = (cells[iDate] || '').slice(0, 10);
  if (!day) continue;
  const credits = Number((cells[iCredits] || '0').replace(/[^0-9.\-]/g, '')) || 0;
  const actions = iActions === -1 ? 0 : Number((cells[iActions] || '0').replace(/[^0-9.\-]/g, '')) || 0;
  byDay[day] = byDay[day] || { dataCredits: 0, actions: 0, tables: new Set(), integrations: new Set() };
  byDay[day].dataCredits += credits;
  byDay[day].actions += actions;
  if (iTable !== -1 && cells[iTable]) byDay[day].tables.add(cells[iTable]);
  if (iIntegration !== -1 && cells[iIntegration]) byDay[day].integrations.add(cells[iIntegration]);
}

const days = Object.keys(byDay).sort();
const newest = days[days.length - 1];
const ageHours = newest ? (Date.now() - Date.parse(`${newest}T23:59:59Z`)) / 3600000 : 9999;
const staleAfter = Number($env.CLAY_EXPORT_STALE_HOURS || 36);

return days.map((day) => ({
  json: {
    vendor: 'clay',
    ok: true,
    day,
    dataCredits: byDay[day].dataCredits,
    actions: byDay[day].actions,
    tables: [...byDay[day].tables],
    integrations: [...byDay[day].integrations],
    // A stale export makes burn look flat, which is indistinguishable from a
    // genuine drop in spend. Tag it and let the alert node route it separately.
    stale: ageHours > staleAfter,
    exportAgeHours: Math.round(ageHours),
    checkedAt: now,
  },
}));

// Per-row events posted by a Clay HTTP API column while a table runs.
// This is the only real-time view of Clay spend available, and it is also the
// only place a "verified" flag exists — the CSV export does not carry one, so
// cost-per-verified-record cannot be computed from the export alone.

const store = $getWorkflowStaticData('global');
store.clayLedger = store.clayLedger || [];

const now = new Date();
const out = [];

for (const item of $input.all()) {
  const b = item.json.body ?? item.json;
  const rowId = b.rowId || b.row_id;
  if (!rowId) {
    out.push({ json: { accepted: false, reason: 'missing rowId', ledgerKey: null } });
    continue;
  }

  const key = `${b.table || 'unknown'}::${rowId}`;
  // Clay retries a failed HTTP column, so the same row can arrive twice.
  if (store.clayLedger.some((e) => e.key === key)) {
    out.push({ json: { accepted: true, duplicate: true, ledgerKey: key } });
    continue;
  }

  const entry = {
    key,
    day: now.toISOString().slice(0, 10),
    ts: now.getTime(),
    table: b.table || 'unknown',
    workbook: b.workbook || null,
    integration: b.integration || b.provider || 'unknown',
    dataCredits: Number(b.dataCredits ?? b.credits ?? 0) || 0,
    actions: Number(b.actions ?? 1) || 1,   // the HTTP column itself consumes 1 Action
    verified: b.verified === true || b.verified === 'true',
  };

  store.clayLedger.push(entry);
  out.push({ json: { accepted: true, duplicate: false, ledgerKey: key } });
}

// Ring-buffer at 45 days so static data cannot grow without bound.
const cutoff = now.getTime() - 45 * 86400000;
store.clayLedger = store.clayLedger.filter((e) => e.ts >= cutoff);

return out;

// One record per (vendor, unit, day) with a dollar figure attached.
//
// Pricing note: Clay's plan fee buys Data Credits AND Actions together, so
// attributing dollars to one unit is a modelling choice, not a vendor number.
// The default split is 70/30 to Data Credits and is overridable. Published plan
// anchors (clay.com/pricing, checked 2026-08-05): Launch $185/mo = 2,500 Data
// Credits + 15,000 Actions; Growth $495/mo = 6,000 + 40,000; annual billing is
// 10% lower ($167 / $446 per month).
// Apollo and ZoomInfo unit prices are contract-specific and MUST come from env.
// If a unit price is missing the record still flows with usdSpend = null — the
// unit-burn and expiry branches work without dollars; only drift needs them.

const num = (v, d) => (v === undefined || v === null || v === '' ? d : Number(v));

const CLAY_PLAN_USD   = num($env.CLAY_PLAN_MONTHLY_USD, 495);
const CLAY_DC_ALLOW   = num($env.CLAY_DATA_CREDIT_ALLOWANCE, 6000);
const CLAY_ACT_ALLOW  = num($env.CLAY_ACTION_ALLOWANCE, 40000);
const CLAY_DC_SHARE   = num($env.CLAY_DATA_CREDIT_COST_SHARE, 0.7);

const clayDcUsd  = CLAY_DC_ALLOW  > 0 ? (CLAY_PLAN_USD * CLAY_DC_SHARE) / CLAY_DC_ALLOW : null;
const clayActUsd = CLAY_ACT_ALLOW > 0 ? (CLAY_PLAN_USD * (1 - CLAY_DC_SHARE)) / CLAY_ACT_ALLOW : null;

const apolloUsd = $env.APOLLO_CREDIT_USD ? Number($env.APOLLO_CREDIT_USD) : null;
const ziUsd     = $env.ZOOMINFO_RECORD_USD ? Number($env.ZOOMINFO_RECORD_USD) : null;

const today = new Date().toISOString().slice(0, 10);
const out = [];

for (const item of $input.all()) {
  const r = item.json;
  if (r.ok === false) { out.push({ json: { ...r, kind: 'health' } }); continue; }

  if (r.vendor === 'clay') {
    out.push({ json: { kind: 'usage', vendor: 'clay', unit: 'data_credit', day: r.day, used: r.dataCredits,
      allowance: CLAY_DC_ALLOW, unitUsd: clayDcUsd, usdSpend: clayDcUsd === null ? null : r.dataCredits * clayDcUsd,
      stale: !!r.stale, integrations: r.integrations ?? [] } });
    out.push({ json: { kind: 'usage', vendor: 'clay', unit: 'action', day: r.day, used: r.actions,
      allowance: CLAY_ACT_ALLOW, unitUsd: clayActUsd, usdSpend: clayActUsd === null ? null : r.actions * clayActUsd,
      stale: !!r.stale, integrations: r.integrations ?? [] } });
    continue;
  }

  if (r.vendor === 'apollo') {
    // Ledger-first: the bracket is the bound, not the number. Midpoint is used
    // only when no call-site ledger figure is available for the day.
    const mid = Math.round((r.derivedCreditFloor + r.derivedCreditCeiling) / 2);
    out.push({ json: { kind: 'usage', vendor: 'apollo', unit: 'credit', day: today, used: mid,
      usedFloor: r.derivedCreditFloor, usedCeiling: r.derivedCreditCeiling, estimated: true,
      allowance: r.allowance, cycleEnd: r.cycleEnd, unitUsd: apolloUsd,
      usdSpend: apolloUsd === null ? null : mid * apolloUsd, requestsToday: r.requestsToday } });
    continue;
  }

  if (r.vendor === 'zoominfo') {
    if (!r.billable) { out.push({ json: { kind: 'throughput', vendor: 'zoominfo', unit: r.unit, used: r.used,
      allowance: r.allowance, remaining: r.remaining, day: today } }); continue; }
    out.push({ json: { kind: 'usage', vendor: 'zoominfo', unit: r.unit, day: today, used: r.used,
      allowance: r.allowance, remaining: r.remaining, cycleEnd: $env.ZOOMINFO_CONTRACT_END || null,
      unitUsd: ziUsd, usdSpend: ziUsd === null ? null : r.used * ziUsd } });
  }
}

return out;

// Cost per verified record (CPVR) = dollars spent / records that passed verification.
// "Verified" comes from the Clay ledger's verified flag — the enrichment is only
// worth what survives verification, so an unverified-row denominator would hide
// exactly the regression this flow exists to catch.
//
// Drift fires when the trailing 7-day CPVR exceeds the trailing 28-day baseline
// by more than CPVR_DRIFT_PCT. A 28-day baseline is long enough to survive one
// bad week and short enough to move when a provider is genuinely repriced.

const store = $getWorkflowStaticData('global');
const ledger = store.clayLedger || [];
const items = $input.all().map((i) => i.json);

const driftPct = Number($env.CPVR_DRIFT_PCT || 25);
const minDenom = Number($env.CPVR_MIN_VERIFIED || 250);

const dayMs = 86400000;
const now = Date.now();
const inWindow = (ts, days) => ts >= now - days * dayMs;

const verified7  = ledger.filter((e) => inWindow(e.ts, 7)  && e.verified).length;
const verified28 = ledger.filter((e) => inWindow(e.ts, 28) && e.verified).length;

const spendInWindow = (days) => {
  const cutoff = new Date(now - days * dayMs).toISOString().slice(0, 10);
  return items
    .filter((r) => r.kind === 'usage' && r.usdSpend !== null && r.usdSpend !== undefined && (r.day || '') >= cutoff)
    .reduce((sum, r) => sum + r.usdSpend, 0);
};

const spend7 = spendInWindow(7);
const spend28 = spendInWindow(28);

// Small denominators make CPVR explode: 12 verified rows on a quiet Sunday
// produces a number that is arithmetically correct and operationally meaningless.
if (verified7 < minDenom || verified28 < minDenom) {
  return [{ json: { kind: 'cpvr', status: 'insufficient_data', verified7, verified28, minDenom,
    note: `Need ${minDenom} verified records in both windows before drift can fire.` } }];
}

const cpvr7 = spend7 / verified7;
const cpvr28 = spend28 / verified28;
const deltaPct = cpvr28 === 0 ? 0 : ((cpvr7 - cpvr28) / cpvr28) * 100;

const worst = items
  .filter((r) => r.kind === 'usage' && Array.isArray(r.integrations) && r.integrations.length > 0)
  .flatMap((r) => r.integrations.map((p) => ({ provider: p, usd: r.usdSpend ?? 0 })))
  .reduce((acc, e) => { acc[e.provider] = (acc[e.provider] || 0) + e.usd; return acc; }, {});

return [{
  json: {
    kind: 'cpvr',
    status: deltaPct > driftPct ? 'drift' : 'ok',
    cpvr7: Number(cpvr7.toFixed(4)),
    cpvr28: Number(cpvr28.toFixed(4)),
    deltaPct: Number(deltaPct.toFixed(1)),
    thresholdPct: driftPct,
    spend7: Number(spend7.toFixed(2)),
    spend28: Number(spend28.toFixed(2)),
    verified7,
    verified28,
    topProviders: Object.entries(worst).sort((a, b) => b[1] - a[1]).slice(0, 3)
      .map(([provider, usd]) => ({ provider, usd: Number(usd.toFixed(2)) })),
  },
}];

// Two failure directions, one node:
//   overrun  — run rate exhausts the allowance before the cycle ends
//   forfeit  — allowance goes unused and expires
//
// Rollover rules differ per vendor and they are the whole point of the alert:
//   Clay Actions      — no rollover, unused Actions expire at cycle end
//   Clay Data Credits — roll over up to 2x the monthly allowance (monthly plans);
//                       annual plans roll 15% when renewing at the same tier or higher
//   Apollo            — credits do not roll over; they expire at the billing anniversary
//   ZoomInfo          — contract-period limits; usageRemaining at contract end is lost

const items = $input.all().map((i) => i.json).filter((r) => r.kind === 'usage');
const forfeitPct = Number($env.FORFEIT_ALERT_PCT || 15);
const warnDays = Number($env.CYCLE_WARN_DAYS || 7);

const cycleEnds = {
  clay: $env.CLAY_CYCLE_END || null,
  apollo: $env.APOLLO_CYCLE_END || null,
  zoominfo: $env.ZOOMINFO_CONTRACT_END || null,
};

const rollover = {
  'clay:action': { rolls: false, capMultiple: 0 },
  'clay:data_credit': { rolls: true, capMultiple: Number($env.CLAY_DC_ROLLOVER_MULTIPLE || 2) },
  'apollo:credit': { rolls: false, capMultiple: 0 },
  'zoominfo:record': { rolls: false, capMultiple: 0 },
  'zoominfo:uniqueID': { rolls: false, capMultiple: 0 },
};

const byKey = {};
for (const r of items) {
  const k = `${r.vendor}:${r.unit}`;
  byKey[k] = byKey[k] || { vendor: r.vendor, unit: r.unit, used: 0, allowance: r.allowance ?? null, unitUsd: r.unitUsd ?? null, days: new Set() };
  byKey[k].used += r.used || 0;
  if (r.day) byKey[k].days.add(r.day);
  if (r.allowance) byKey[k].allowance = r.allowance;
}

const out = [];
for (const [key, v] of Object.entries(byKey)) {
  const end = cycleEnds[v.vendor];
  if (!end) {
    // Guessing a cycle boundary would produce confident nonsense. Skip instead.
    out.push({ json: { kind: 'expiry', status: 'no_cycle_configured', vendor: v.vendor, unit: v.unit,
      note: `Set ${v.vendor.toUpperCase()}_CYCLE_END (YYYY-MM-DD) to enable the expiry forecast.` } });
    continue;
  }
  if (!v.allowance) {
    out.push({ json: { kind: 'expiry', status: 'no_allowance_configured', vendor: v.vendor, unit: v.unit } });
    continue;
  }

  const daysObserved = Math.max(v.days.size, 1);
  const runRate = v.used / daysObserved;
  const daysLeft = Math.ceil((Date.parse(`${end}T23:59:59Z`) - Date.now()) / 86400000);
  const projectedUse = v.used + runRate * Math.max(daysLeft, 0);
  const projectedUnused = Math.max(v.allowance - projectedUse, 0);
  const roll = rollover[key] || { rolls: false, capMultiple: 0 };
  const carried = roll.rolls ? Math.min(projectedUnused, v.allowance * roll.capMultiple) : 0;
  const forfeit = Math.max(projectedUnused - carried, 0);
  const forfeitShare = (forfeit / v.allowance) * 100;

  let status = 'ok';
  if (projectedUse > v.allowance) status = 'overrun';
  else if (daysLeft <= warnDays && forfeitShare >= forfeitPct) status = 'forfeit';

  out.push({
    json: {
      kind: 'expiry', status, vendor: v.vendor, unit: v.unit,
      used: Math.round(v.used), allowance: v.allowance, daysLeft,
      runRatePerDay: Number(runRate.toFixed(1)),
      projectedUse: Math.round(projectedUse),
      projectedForfeit: Math.round(forfeit),
      forfeitSharePct: Number(forfeitShare.toFixed(1)),
      forfeitUsd: v.unitUsd === null ? null : Number((forfeit * v.unitUsd).toFixed(2)),
      rollsOver: roll.rolls, rolloverCapMultiple: roll.capMultiple,
      cycleEnd: end,
    },
  });
}

return out;

// One alert per (kind, vendor, unit, status) per bucket. Without this the hourly
// sweep re-posts the same forfeit warning 24 times a day and the channel gets muted,
// which is the failure mode that kills every monitoring flow.
//
// Static data persists on production executions only — never on manual runs — so
// verify this gate with an activated schedule, not the Execute Workflow button.

const store = $getWorkflowStaticData('global');
store.alerted = store.alerted || {};

const bucketHours = Number($env.ALERT_DEDUP_HOURS || 12);
const bucket = Math.floor(Date.now() / (bucketHours * 3600000));
const out = [];

for (const item of $input.all()) {
  const r = item.json;
  const status = r.status ?? (r.ok === false ? 'health' : 'ok');
  if (['ok', 'insufficient_data', 'no_cycle_configured', 'no_allowance_configured'].includes(status)) continue;

  const key = `${r.kind}:${r.vendor ?? 'all'}:${r.unit ?? 'all'}:${status}:${bucket}`;
  if (store.alerted[key]) continue;
  store.alerted[key] = Date.now();

  const severity = status === 'overrun' || status === 'drift' ? 'critical' : 'warning';
  out.push({ json: { ...r, alertKey: key, severity, status } });
}

// Drop dedup keys older than 3 days.
const cutoff = Date.now() - 3 * 86400000;
for (const [k, ts] of Object.entries(store.alerted)) if (ts < cutoff) delete store.alerted[k];

return out;

const blocks = [];
const r = $json;

const titles = {
  drift: `Cost per verified record up ${r.deltaPct}% vs the 28-day baseline`,
  overrun: `${r.vendor} ${r.unit} allowance will be exhausted before ${r.cycleEnd}`,
  forfeit: `${r.vendor} ${r.unit}: ${r.projectedForfeit} units expire ${r.cycleEnd}`,
  health: `${r.vendor} usage poll failed: ${r.reason}`,
};
const title = titles[r.status] ?? `Enrichment credit alert: ${r.status}`;
const emoji = r.severity === 'critical' ? ':rotating_light:' : ':warning:';

blocks.push({ type: 'header', text: { type: 'plain_text', text: `${emoji} ${title}`.slice(0, 150), emoji: true } });

const fields = [];
const push = (label, value) => { if (value !== null && value !== undefined && value !== '') fields.push({ type: 'mrkdwn', text: `*${label}*\n${value}` }); };

if (r.kind === 'cpvr') {
  push('CPVR (7d)', `$${r.cpvr7}`);
  push('CPVR (28d baseline)', `$${r.cpvr28}`);
  push('Verified records (7d)', r.verified7);
  push('Spend (7d)', `$${r.spend7}`);
  if (r.topProviders?.length) push('Top spend', r.topProviders.map((p) => `${p.provider} $${p.usd}`).join('\n'));
} else if (r.kind === 'expiry') {
  push('Used / allowance', `${r.used} / ${r.allowance}`);
  push('Run rate', `${r.runRatePerDay}/day`);
  push('Days left in cycle', r.daysLeft);
  push('Projected at cycle end', r.projectedUse);
  if (r.status === 'forfeit') push('Forfeit', `${r.projectedForfeit} (${r.forfeitSharePct}%)${r.forfeitUsd ? ` ≈ $${r.forfeitUsd}` : ''}`);
  push('Rolls over', r.rollsOver ? `yes, cap ${r.rolloverCapMultiple}x allowance` : 'no — use it or lose it');
}

if (fields.length) blocks.push({ type: 'section', fields: fields.slice(0, 10) });

const actions = {
  drift: 'Open the Clay table credit-usage dashboard, sort columns by spend, and check whether a waterfall added a paid step or a provider changed its per-row price.',
